public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    if (nums == null || nums.length == 0) {
        return res;
    }
    boolean[] used = new boolean[nums.length];
    List<Integer> current = new ArrayList<>();
    backtrack(nums, used, current, res);
    return res;
}

private void backtrack(int[] nums, boolean[] used, List<Integer> current, List<List<Integer>> res) {
    if (current.size() == nums.length) {
        res.add(new ArrayList<>(current));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (!used[i]) {
            used[i] = true;
            current.add(nums[i]);
            backtrack(nums, used, current, res);
            current.remove(current.size() - 1);
            used[i] = false;
        }
    }
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // If any string is empty, no common substring exists
    for (String s : strings) {
        if (s == null || s.isEmpty()) {
            return 0;
        }
    }
    String first = strings.get(0);
    int maxLen = first.length();
    for (int len = maxLen; len >= 1; len--) {
        // Generate all substrings of length len from the first string
        for (int i = 0; i <= first.length() - len; i++) {
            String sub = first.substring(i, i + len);
            String rev = new StringBuilder(sub).reverse().toString();
            boolean allMatch = true;
            for (int idx = 1; idx < strings.size(); idx++) {
                String other = strings.get(idx);
                if (!(other.contains(sub) || other.contains(rev))) {
                    allMatch = false;
                    break;
                }
            }
            if (allMatch) {
                return len;
            }
        }
    }
    return 0;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }
    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int deposits = 0;
    int[] dRow = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dCol = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                deposits++;
                // DFS stack
                java.util.Deque<int[]> stack = new java.util.ArrayDeque<>();
                stack.push(new int[]{r, c});
                visited[r][c] = true;
                while (!stack.isEmpty()) {
                    int[] pos = stack.pop();
                    int cr = pos[0];
                    int cc = pos[1];
                    for (int k = 0; k < 8; k++) {
                        int nr = cr + dRow[k];
                        int nc = cc + dCol[k];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols
                                && grid[nr][nc] == '@' && !visited[nr][nc]) {
                            visited[nr][nc] = true;
                            stack.push(new int[]{nr, nc});
                        }
                    }
                }
            }
        }
    }
    return deposits;
}

