public String sortString(String s) {
    if (s == null) {
        return null;
    }
    int n = s.length();
    if (n == 0) {
        return "";
    }
    int[] freq = new int[26];
    for (char c : s.toCharArray()) {
        if (c < 'a' || c > 'z') {
            // If the string contains characters outside 'a'-'z', throw an exception
            throw new IllegalArgumentException("Input string must contain only lowercase letters a-z.");
        }
        freq[c - 'a']++;
    }
    StringBuilder result = new StringBuilder(n);
    while (result.length() < n) {
        // Ascending pass: pick smallest available characters
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) {
                result.append((char) (i + 'a'));
                freq[i]--;
            }
        }
        // Descending pass: pick largest available characters
        for (int i = 25; i >= 0; i--) {
            if (freq[i] > 0) {
                result.append((char) (i + 'a'));
                freq[i]--;
            }
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int sum = 0;
    for (int num : nums) sum += num;
    // dp[i] will contain all possible sums using exactly i numbers
    java.util.List<java.util.Set<Integer>> dp = new java.util.ArrayList<>(n + 1);
    for (int i = 0; i <= n; i++) dp.add(new java.util.HashSet<>());
    dp.get(0).add(0);
    for (int num : nums) {
        // iterate sizes in reverse to avoid using the same number twice
        for (int size = n - 1; size >= 0; size--) {
            if (dp.get(size).isEmpty()) continue;
            java.util.Set<Integer> current = dp.get(size);
            java.util.Set<Integer> targetSet = dp.get(size + 1);
            for (int s : current) {
                targetSet.add(s + num);
            }
        }
    }
    for (int k = 1; k < n; k++) {
        if ((sum * k) % n != 0) continue;
        int target = (sum * k) / n;
        if (dp.get(k).contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    // dp[i] is the minimum cost to reach step i
    // We only need the last two values
    int prev2 = 0; // cost to reach step 0
    int prev1 = 0; // cost to reach step 1
    for (int i = 2; i <= n; i++) {
        int costToStep = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
        prev2 = prev1;
        prev1 = costToStep;
    }
    return prev1;
}

public int uniqueMorseRepresentations(String[] words) {
    if (words == null || words.length == 0) {
        return 0;
    }
    String[] morse = {".-","-...","-.-.","-..",".","..-.","--.","....","..",
                      ".---","-.-",".-..","--","-.","---",".--.","--.-",".-.",
                      "...","-","..-","...-",".--","-..-","-.--","--.."};
    java.util.Set<String> set = new java.util.HashSet<>();
    for (String word : words) {
        if (word == null) {
            continue;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < word.length(); i++) {
            char c = word.charAt(i);
            if (c >= 'a' && c <= 'z') {
                sb.append(morse[c - 'a']);
            } else if (c >= 'A' && c <= 'Z') {
                sb.append(morse[c - 'A']);
            } // ignore non-letter characters
        }
        set.add(sb.toString());
    }
    return set.size();
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) {
        return false;
    }
    int total = 1 << k; // number of possible binary strings of length k
    if (s.length() < total) {
        return false;
    }
    boolean[] seen = new boolean[total];
    int mask = total - 1;
    int code = 0;
    for (int i = 0; i < s.length(); i++) {
        code = ((code << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            seen[code] = true;
        }
    }
    for (boolean b : seen) {
        if (!b) {
            return false;
        }
    }
    return true;
}

