public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int balance = 0;      // number of unmatched '('
    int insertions = 0;   // number of insertions needed

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            balance--;
            if (balance < 0) {
                // Need an extra '(' before this ')'
                insertions++;
                balance = 0;
            }
        } else {
            // According to the problem statement, s contains only '(' and ')'.
            // If other characters appear, they are ignored.
        }
    }

    // Any remaining unmatched '(' need ')' inserted
    insertions += balance;
    return insertions;
}

