public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int maxEnding = nums[0];
    int maxSoFar = nums[0];
    int minEnding = nums[0];
    int minSoFar = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int val = nums[i];
        maxEnding = Math.max(val, maxEnding + val);
        maxSoFar = Math.max(maxSoFar, maxEnding);
        minEnding = Math.min(val, minEnding + val);
        minSoFar = Math.min(minSoFar, minEnding);
    }
    return Math.max(maxSoFar, -minSoFar);
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0; // No positive Fibonacci numbers needed for non‑positive k
    }

    // Generate all Fibonacci numbers up to k
    java.util.List<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1);
    fibs.add(1);
    while (true) {
        int sz = fibs.size();
        int next = fibs.get(sz - 1) + fibs.get(sz - 2);
        if (next > k) {
            break;
        }
        fibs.add(next);
    }

    int count = 0;
    int remaining = k;

    // Greedy: subtract the largest Fibonacci number <= remaining
    for (int i = fibs.size() - 1; i >= 0 && remaining > 0; i--) {
        int f = fibs.get(i);
        if (f <= remaining) {
            remaining -= f;
            count++;
        }
    }

    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.ArrayList<Integer> factors = new java.util.ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            factors.add(i);
            int other = n / i;
            if (other != i) {
                factors.add(other);
            }
        }
    }
    java.util.Collections.sort(factors);
    if (k > factors.size()) {
        return -1;
    }
    return factors.get(k - 1);
}

public String makeGood(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char last = stack.charAt(len - 1);
            // Check if c and last are the same letter with opposite cases
            if (Math.abs(c - last) == 32) {
                stack.deleteCharAt(len - 1);
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
