    return dfs(0, new java.util.HashSet<>(), s);
}

private int dfs(int idx, java.util.Set<String> used, String s) {
    if (idx == s.length()) {
        return used.size();
    }
    int best = 0;
    for (int i = idx; i < s.length(); i++) {
        String sub = s.substring(idx, i + 1);
        if (!used.contains(sub)) {
            used.add(sub);
            best = Math.max(best, dfs(i + 1, used, s));
            used.remove(sub);
        }
    }
    return best;
}

public int minOperations(String[] logs) {
    if (logs == null || logs.length == 0) {
        return 0;
    }
    int depth = 0;
    for (String log : logs) {
        if (log == null) {
            continue;
        }
        switch (log) {
            case "../":
                if (depth > 0) {
                    depth--;
                }
                break;
            case "./":
                // stay in the same folder
                break;
            default:
                // any other string represents entering a subfolder
                depth++;
                break;
        }
    }
    return depth;
}

public String getSmallestString(int n, int k) {
    if (n <= 0) {
        return "";
    }
    int minSum = n;          // all 'a'
    int maxSum = 26 * n;     // all 'z'
    if (k < minSum || k > maxSum) {
        return "";
    }
    char[] result = new char[n];
    Arrays.fill(result, 'a');
    int remaining = k - minSum;
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining);
        result[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(result);
}

