    // dp[i][j][d] where d: 0=horizontal, 1=vertical, 2=diagonal, 3=anti-diagonal
    int[][][] dp = new int[m][n][4];
    int maxLen = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dp[i][j][0] = (j > 0 ? dp[i][j - 1][0] : 0) + 1;          // horizontal
                dp[i][j][1] = (i > 0 ? dp[i - 1][j][1] : 0) + 1;          // vertical
                dp[i][j][2] = (i > 0 && j > 0 ? dp[i - 1][j - 1][2] : 0) + 1; // diagonal
                dp[i][j][3] = (i > 0 && j < n - 1 ? dp[i - 1][j + 1][3] : 0) + 1; // anti-diagonal
                int cellMax = Math.max(Math.max(dp[i][j][0], dp[i][j][1]),
                                        Math.max(dp[i][j][2], dp[i][j][3]));
                if (cellMax > maxLen) {
                    maxLen = cellMax;
                }
            }
        }
    }
    return maxLen;
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    boolean negative = n < 0;
    long absVal = Math.abs((long) n); // use long to handle Integer.MIN_VALUE
    StringBuilder sb = new StringBuilder();
    int digitCount = 0;
    while (absVal > 0) {
        sb.append(absVal % 10);
        absVal /= 10;
        digitCount++;
        if (absVal > 0 && digitCount % 3 == 0) {
            sb.append('.');
        }
    }
    if (negative) {
        sb.append('-');
    }
    return sb.reverse().toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    // Sort to handle duplicates
    java.util.Arrays.sort(A);
    int maxVal = A[n - 1];
    int maxSum = 2 * maxVal;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }
    int allMask = (1 << n) - 1;
    int[][] memo = new int[n + 1][1 << n];
    for (int i = 0; i <= n; i++) {
        java.util.Arrays.fill(memo[i], -1);
    }
    java.util.function.IntBinaryOperator dfs = new java.util.function.IntBinaryOperator() {
        @Override
        public int applyAsInt(int last, int mask) {
            if (mask == allMask) return 1;
            if (memo[last][mask] != -1) return memo[last][mask];
            long total = 0;
            for (int j = 0; j < n; j++) {
                if ((mask & (1 << j)) != 0) continue;
                if (last != n && !isSquare[A[last] + A[j]]) continue;
                // Skip duplicates: if current value equals previous and previous not used
                if (j > 0 && A[j] == A[j - 1] && (mask & (1 << (j - 1))) == 0) continue;
                total += applyAsInt(j, mask | (1 << j));
            }
            memo[last][mask] = (int) total;
            return memo[last][mask];
        }
    };
    long result = 0;
    for (int i = 0; i < n; i++) {
        // Skip duplicates for starting element
        if (i > 0 && A[i] == A[i - 1]) continue;
        result += dfs.applyAsInt(i, 1 << i);
    }
    return (int) result;
}

