public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int maxArea = 0;
    java.util.ArrayDeque<Integer> stack = new java.util.ArrayDeque<>();
    for (int i = 0; i <= n; i++) {
        int h = (i == n) ? 0 : heights[i];
        while (!stack.isEmpty() && h < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    try {
        if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
            return new int[0];
        }
        int m = mat.length;
        int n = mat[0].length;
        for (int r = 0; r < m; r++) {
            if (mat[r] == null || mat[r].length != n) {
                throw new IllegalArgumentException("All rows must have the same number of columns");
            }
        }
        int[] res = new int[m * n];
        int index = 0;
        int i = 0, j = 0;
        boolean up = true;
        while (index < res.length) {
            res[index++] = mat[i][j];
            if (up) {
                if (j == n - 1) {
                    i++;
                    up = false;
                } else if (i == 0) {
                    j++;
                    up = false;
                } else {
                    i--;
                    j++;
                }
            } else {
                if (i == m - 1) {
                    j++;
                    up = true;
                } else if (j == 0) {
                    i++;
                    up = true;
                } else {
                    i++;
                    j--;
                }
            }
        }
        return res;
    } catch (Exception e) {
        return new int[0];
    }
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    char[] digits = Integer.toString(n).toCharArray();
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1; // no higher permutation
    }
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    // swap
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // reverse suffix
    int left = i + 1, right = digits.length - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }
    int result = Integer.parseInt(new String(digits));
    return result > n ? result : -1;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    int[] p0 = points[0];
    int[] p1 = points[1];
    int[] p2 = points[2];
    // Check for duplicate points
    if ((p0[0] == p1[0] && p0[1] == p1[1]) ||
        (p0[0] == p2[0] && p0[1] == p2[1]) ||
        (p1[0] == p2[0] && p1[1] == p2[1])) {
        return false;
    }
    // Compute twice the signed area of the triangle
    long area2 = (long)(p1[0] - p0[0]) * (p2[1] - p0[1]) -
                 (long)(p2[0] - p0[0]) * (p1[1] - p0[1]);
    return area2 != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int next = Math.min(next2, Math.min(next3, next5));
        ugly[i] = next;
        if (next == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (next == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (next == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int maxLen = 1;
    int currentLen = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentLen++;
        } else {
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
            currentLen = 1;
        }
    }
    if (currentLen > maxLen) {
        maxLen = currentLen;
    }
    return maxLen;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> res = new ArrayList<>();
    if (n <= 0) return res;
    int cur = 1;
    for (int i = 0; i < n; i++) {
        res.add(cur);
        if (cur <= n / 10) {
            cur *= 10;
        } else {
            while (cur % 10 == 9 || cur == n) {
                cur /= 10;
            }
            cur++;
        }
    }
    return res;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : nums) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    // Check if n is a perfect square
    int sqrtN = (int) Math.sqrt(n);
    if (sqrtN * sqrtN == n) {
        return 1;
    }
    // Check if n can be expressed as sum of two perfect squares
    for (int i = 1; i <= sqrtN; i++) {
        int remainder = n - i * i;
        int sqrtR = (int) Math.sqrt(remainder);
        if (sqrtR * sqrtR == remainder) {
            return 2;
        }
    }
    // Legendre's three-square theorem
    int temp = n;
    while (temp % 4 == 0) {
        temp /= 4;
    }
    if (temp % 8 == 7) {
        return 4;
    }
    return 3;
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c != ' ') {
            word.append(c);
        } else {
            result.append(word.reverse());
            word.setLength(0);
            result.append(' ');
        }
    }
    // Append the last word if any
    result.append(word.reverse());
    return result.toString();
}
